1→import { randomUUID } from 'node:crypto';
2→const typed = (message, code) => Object.assign(new Error(message), { code });
3→const record = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
4→const json = (value) => JSON.parse(JSON.stringify(value));
5→const ACI_STATUSES = new Set(['ok', 'partial', 'error', 'needs_resume', 'diverged']);
6→function jsonValue(value, seen = new Set()) {
7→  if (value === null || typeof value === 'string' || typeof value === 'boolean') return true;
8→  if (typeof value === 'number') return Number.isFinite(value);
9→  if (typeof value !== 'object' || seen.has(value)) return false;
10→  seen.add(value);
11→  const values = Array.isArray(value)
12→    ? value
13→    : Object.getPrototypeOf(value) === Object.prototype
14→      ? Object.values(value)
15→      : null;
16→  const valid = values !== null && values.every((item) => jsonValue(item, seen));
17→  seen.delete(value);
18→  return valid;
19→}
20→function validRef(ref) {
21→  if (!record(ref) || typeof ref.kind !== 'string' || ref.kind.length === 0 || Buffer.byteLength(ref.kind) > 128) return false;
22→  const handle = typeof ref.handle === 'string' && ref.handle.length > 0 && Buffer.byteLength(ref.handle) <= 4_096;
23→  const digest = typeof ref.digest === 'string' && /^[a-f0-9]{64}$/i.test(ref.digest);
24→  if (!handle && !digest) return false;
25→  return (!Object.hasOwn(ref, 'bytes') || (Number.isSafeInteger(ref.bytes) && ref.bytes >= 0)) && jsonValue(ref);
26→}
27→function validCost(cost) {
28→  return record(cost) && Number.isSafeInteger(cost.tokens_out) && cost.tokens_out >= 0
29→    && Number.isSafeInteger(cost.wall_ms) && cost.wall_ms >= 0
30→    && typeof cost.usd === 'number' && Number.isFinite(cost.usd) && cost.usd >= 0
31→    && typeof cost.underlying === 'string' && cost.underlying.length > 0 && Buffer.byteLength(cost.underlying) <= 256;
32→}
33→function validResult(value, op) {
34→  const cursorPresent = record(value) && Object.hasOwn(value, 'cursor');
35→  return record(value) && value.op === op && ACI_STATUSES.has(value.status)
36→    && typeof value.summary === 'string' && Buffer.byteLength(value.summary) <= 2_048 && !value.summary.includes('\0')
