7→
8→import { AtlasStructuralDelta, CapabilityRegistry, createDriver } from '../src/index.mjs';
9→
10→const root = (name) => mkdtempSync(join(tmpdir(), `baton-capability-${name}-`));
11→const envelope = (op, value = 1, overrides = {}) => ({
12→  op,
13→  status: 'ok',
14→  summary: 'bounded result',
15→  payload: [{ value }],
16→  refs: [{ kind: 'test', digest: 'a'.repeat(64) }],
17→  cost: { tokens_out: 4, wall_ms: 1, usd: 0, underlying: 'fixture' },
18→  provenance: { deterministic: true, mergeAuthority: false, verificationAuthority: false },
19→  ...overrides,
20→});
21→
22→function fixture(overrides = {}) {
23→  const calls = [];
24→  return {
25→    calls,
26→    card() { return { name: 'fixture', version: '1', ops: { 'fixture.read': { reverifiable: true } } }; },
27→    async invoke(op, args, ctx) { calls.push({ action: 'invoke', op, args, ctx }); return envelope(op); },
28→    async resume(ref, cursor, ctx) { calls.push({ action: 'resume', ref, cursor, ctx }); return envelope('fixture.read'); },
29→    async reverify(claim, op, args, ctx) { calls.push({ action: 'reverify', claim, op, args, ctx }); return { ok: claim.digest === args.digest }; },
30→    ...overrides,
31→  };
32→}
33→
34→const registry = (capability = fixture(), overrides = {}) => new CapabilityRegistry({
35→  capabilities: { fixture: capability },
36→  maxBudgetTokens: 1_000,
37→  maxEnvelopeBytes: 64 * 1024,
38→  root: '/trusted/repository',
39→  record: () => {},
40→  ...overrides,
41→});
