43→test('CI1/CI2/CI5/CI7: closed cards invoke with trusted context and bounded provenance-only audit', async () => {
44→  const capability = fixture(); const events = [];
45→  const subject = registry(capability, { record: (event) => events.push(event) });
46→  assert.deepEqual(subject.cards(), [{
47→    name: 'fixture', version: '1', ops: { 'fixture.read': { reverifiable: true } },
48→    actions: { invoke: true, resume: true, reverify: true, cancel: false },
49→    northbound: { inlineOps: ['fixture.read'], taskOpsRequiringTaskPlane: [] },
50→  }]);
51→  const result = await subject.invoke('fixture', 'fixture.read', { query: 'TOP-SECRET-ARGUMENT' }, { budgetTokens: 100, actor: 'web:user:session' });
52→  assert.equal(result.status, 'ok');
53→  assert.deepEqual(capability.calls[0], {
54→    action: 'invoke', op: 'fixture.read', args: { query: 'TOP-SECRET-ARGUMENT' },
55→    ctx: { budgetTokens: 100, signal: undefined, actor: 'web:user:session', root: '/trusted/repository' },
56→  });
57→  assert.deepEqual(events.map((event) => event.kind), ['capability.op.started', 'capability.op.completed']);
58→  assert.equal(events[0].invocationId, events[1].invocationId);
59→  assert.equal(JSON.stringify(events).includes('TOP-SECRET-ARGUMENT'), false);
60→  assert.deepEqual(events[1].digests, ['a'.repeat(64)]);
61→  assert.deepEqual(events[1].cost, { tokens_out: 4, wall_ms: 1, usd: 0, underlying: 'fixture' });
62→  assert.deepEqual(events[1].refs, [{ kind: 'test', digest: 'a'.repeat(64) }]);
63→});
