65→test('CI1/CI2/CI7: registration, cards, JSON inputs, operations, budgets, and envelopes fail closed', async () => {
66→  assert.throws(() => new CapabilityRegistry({ capabilities: {}, maxBudgetTokens: 1 }), /maxEnvelopeBytes/);
67→  assert.throws(() => new CapabilityRegistry({ capabilities: { fixture: fixture() }, maxBudgetTokens: 1, maxEnvelopeBytes: 1_000 }), /record sink/);
68→  assert.throws(() => new CapabilityRegistry({ capabilities: { bad: {} }, maxBudgetTokens: 1, maxEnvelopeBytes: 100, record: () => {} }), /invalid capability registration/);
