74→  await assert.rejects(registry().invoke('fixture', 'fixture.read', {}, { budgetTokens: 1_001 }), (error) => error.code === 'capability_budget_invalid');
75→  const cyclic = {}; cyclic.self = cyclic;
76→  await assert.rejects(registry().invoke('fixture', 'fixture.read', cyclic, { budgetTokens: 10 }), (error) => error.code === 'capability_args_invalid');
77→  const malformed = fixture({ invoke: async () => ({ op: 'fixture.read', status: 'ok' }) });
78→  await assert.rejects(registry(malformed).invoke('fixture', 'fixture.read', {}, { budgetTokens: 10 }), (error) => error.code === 'capability_result_invalid');
