87→    await assert.rejects(registry(invalid).invoke('fixture', 'fixture.read', {}, { budgetTokens: 100 }), (error) => error.code === 'capability_result_invalid');
88→  }
89→  const resumable = fixture({ invoke: async () => envelope('fixture.read', 1, { status: 'needs_resume', cursor: 'next' }) });
90→  assert.equal((await registry(resumable).invoke('fixture', 'fixture.read', {}, { budgetTokens: 100 })).cursor, 'next');
91→  const oversizedPayload = fixture({ invoke: async (op) => envelope(op, 'x'.repeat(100)) });
92→  await assert.rejects(registry(oversizedPayload).invoke('fixture', 'fixture.read', {}, { budgetTokens: 2 }), (error) => error.code === 'capability_result_oversize');
93→  const oversizedEnvelope = fixture({ invoke: async (op) => envelope(op, 1, { summary: 'x'.repeat(2_000) }) });
94→  await assert.rejects(registry(oversizedEnvelope, { maxEnvelopeBytes: 1_000 }).invoke('fixture', 'fixture.read', {}, { budgetTokens: 100 }), (error) => error.code === 'capability_result_oversize');
95→});
