  assert.equal((await registry(resumable).invoke('fixture', 'fixture.read', {}, { budgetTokens: 100 })).cursor, 'next');
  const oversizedPayload = fixture({ invoke: async (op) => envelope(op, 'x'.repeat(100)) });
