255→test('CI1/CI7: Coordinator exposes one capability registry through its public command boundary', async () => {
256→  const calls = [];
257→  const cards = [{ name: 'atlas', version: '1', ops: { 'atlas.inspect': {} } }];
258→  const result = {
259→    op: 'atlas.inspect', status: 'ok', summary: 'inspected', payload: [], refs: [],
260→    cost: { tokens_out: 1, wall_ms: 1, usd: 0, underlying: 'test' },
261→    provenance: { mergeAuthority: false, verificationAuthority: false },
262→  };
263→  const capabilities = {
264→    cards() { calls.push(['cards']); return cards; },
265→    async invoke(...args) { calls.push(['invoke', ...args]); return result; },
266→    async resume(...args) { calls.push(['resume', ...args]); return result; },
267→    async reverify(...args) { calls.push(['reverify', ...args]); return result; },
268→  };
269→  const { coordinator } = setup({ capabilities });
270→  const ctx = { budgetTokens: 50, actor: 'operator' };
271→
272→  assert.equal(coordinator.capabilityCards(), cards);
273→  assert.equal(await coordinator.invokeCapability('atlas', 'atlas.inspect', { path: 'a.js' }, ctx), result);
274→  assert.equal(await coordinator.resumeCapability('atlas', 'atlas.inspect', { digest: 'sha256:a' }, 'next', ctx), result);
275→  assert.equal(await coordinator.reverifyCapability('atlas', 'atlas.inspect', { digest: 'sha256:a' }, { path: 'a.js' }, ctx), result);
276→  assert.deepEqual(calls, [
277→    ['cards'],
278→    ['invoke', 'atlas', 'atlas.inspect', { path: 'a.js' }, ctx],
279→    ['resume', 'atlas', 'atlas.inspect', { digest: 'sha256:a' }, 'next', ctx],
280→    ['reverify', 'atlas', 'atlas.inspect', { digest: 'sha256:a' }, { path: 'a.js' }, ctx],
281→  ]);
282→});
283→
284→test('CI1/CI7: absent or malformed capability registries fail closed without a side plane', async () => {
