286→  assert.deepEqual(coordinator.capabilityCards(), []);
287→  await assert.rejects(
288→    coordinator.invokeCapability('atlas', 'atlas.inspect', {}, { budgetTokens: 1 }),
289→    (error) => error.code === 'capability_unavailable',
