91→export class AtlasStructuralDelta {
92→  constructor(opts = {}) {
93→    if (typeof opts.artifactRoot !== 'string' || opts.artifactRoot.length === 0) throw new TypeError('Atlas artifactRoot required');
94→    this.artifactRoot = opts.artifactRoot;
95→    this.maxSourceBytes = opts.maxSourceBytes ?? 2 * 1024 * 1024;
96→    this.now = opts.now ?? Date.now;
97→    this.record = opts.record ?? null;
98→    mkdirSync(this.artifactRoot, { recursive: true, mode: 0o700 });
99→  }
100→  card() {
101→    return Object.freeze({
102→      name: 'atlas-structural', version: '0.1.0', underlying: [`@ast-grep/napi@${AST_GREP_VERSION}`],
103→      ops: { 'diff.structural': { latency_class: 'interactive', deterministic: true, side_effects: 'writes_content_addressed_artifact', reverifiable: true } },
104→      languages: Object.keys(LANGUAGE), shared_state: { artifacts: 'content-addressed' }, sandbox_required: 'read_only_worktrees', cost_model: 'cpu_bound_local',
105→      limitations: ['no move/rename matching', 'no semantic equivalence', 'no base-overlay index', 'no SCIP/CPG/IR'],
106→    });
107→  }
108→  async invoke(op, args, ctx) {
109→    if (op !== 'diff.structural') throw Object.assign(new Error(`unsupported Atlas op ${op}`), { code: 'unsupported_op' });
110→    if (!ctx || !ctx.beforeRoot || !ctx.afterRoot || !Number.isInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('Atlas roots and positive budgetTokens required');
111→    const started = this.now();
112→    const beforePath = safePath(ctx.beforeRoot, args.beforePath);
113→    const afterPath = safePath(ctx.afterRoot, args.afterPath);
114→    const language = String(args.language ?? EXTENSION[extname(args.afterPath).toLowerCase()] ?? EXTENSION[extname(args.beforePath).toLowerCase()] ?? '').toLowerCase();
115→    if (!LANGUAGE[language]) throw Object.assign(new Error(`unsupported Atlas language ${language}`), { code: 'unsupported_language' });
116→    const before = readFileSync(beforePath);
117→    const after = readFileSync(afterPath);
118→    if (before.includes(0) || after.includes(0) || before.length > this.maxSourceBytes || after.length > this.maxSourceBytes) throw Object.assign(new Error('source is binary or exceeds Atlas limit'), { code: 'invalid_source' });
119→    const beforeText = before.toString('utf8'); const afterText = after.toString('utf8');
120→    const beforeDigest = sha(before); const afterDigest = sha(after);
121→    this.record?.({ kind: 'capability.op.started', actor: ctx.actor ?? 'orchestrator', op, beforeDigest, afterDigest });
122→    const left = parseUnits(language, beforeText); const right = parseUnits(language, afterText);
123→    const changes = delta(left.units, right.units);
124→    const counts = { added: changes.filter((item) => item.change === 'added').length, removed: changes.filter((item) => item.change === 'removed').length, modified: changes.filter((item) => item.change === 'modified').length };
125→    const complete = { schemaVersion: 1, op, language, before: { path: args.beforePath, digest: beforeDigest, parseErrors: left.errors }, after: { path: args.afterPath, digest: afterDigest, parseErrors: right.errors }, counts, changes };
126→    const serialized = `${JSON.stringify(complete)}\n`; const artifactDigest = sha(serialized);
127→    const artifactPath = join(this.artifactRoot, `${artifactDigest}.json`);
128→    if (!existsSync(artifactPath)) writeFileSync(artifactPath, serialized, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
129→    const budgetBytes = ctx.budgetTokens * 4;
130→    const payload = [];
131→    for (const change of changes) { if (Buffer.byteLength(JSON.stringify([...payload, change])) > budgetBytes) break; payload.push(change); }
132→    const parseErrorCount = left.errors.length + right.errors.length;
133→    const truncated = payload.length < changes.length;
134→    const status = truncated ? 'needs_resume' : (parseErrorCount > 0 ? 'partial' : 'ok');
135→    const wallMs = Math.max(0, this.now() - started);
136→    const result = Object.freeze({
137→      op, status, summary: `${counts.added} added, ${counts.removed} removed, ${counts.modified} modified${parseErrorCount ? `; ${parseErrorCount} parse errors` : ''}`,
138→      payload, refs: [{ handle: `art:sha256:${artifactDigest}`, kind: 'structural_delta', digest: artifactDigest, bytes: Buffer.byteLength(serialized), mediaType: 'application/vnd.baton.atlas-structural+json', path: artifactPath }],
139→      ...(truncated ? { cursor: `atlas:${artifactDigest}:${payload.length}` } : {}),
140→      cost: { tokens_out: Math.ceil(Buffer.byteLength(JSON.stringify(payload)) / 4), wall_ms: wallMs, usd: 0, underlying: `@ast-grep/napi@${AST_GREP_VERSION}` },
141→      provenance: { tool: `@ast-grep/napi@${AST_GREP_VERSION}`, language, beforeDigest, afterDigest, deterministic: true, parseErrors: { before: left.errors.length, after: right.errors.length }, artifactDigest },
142→    });
143→    this.record?.({ kind: 'capability.op.completed', actor: ctx.actor ?? 'orchestrator', op, beforeDigest, afterDigest, artifactDigest, status, wallMs });
144→    return result;
145→  }
146→  async reverify(claim, op, args, ctx) {
147→    const rerun = await this.invoke(op, args, ctx);
148→    return Object.freeze({ ok: rerun.provenance.artifactDigest === claim?.provenance?.artifactDigest, observedDigest: rerun.provenance.artifactDigest });
